INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "梁任李琪为中书侍郎、同平章事。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p005·原文件第20行", "note": "原文：夏，四月，乙亥，以尚书右丞李琪为中书侍郎、同平章事。；核对说明：旧书卷十同记任命，但日次置于该卷条目中；主书日期按原文。", "status": "draft", "id": "cd3b43a6-28ec-517d-967e-a70a8d667b06", "subject_id": "c340f74e-6c94-59c8-a56d-97c4f6264408", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "920年四月乙亥", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p005·原文件第20行", "note": "原文：夏，四月，乙亥，以尚书右丞李琪为中书侍郎、同平章事。；核对说明：按主书本段纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "3d2d8766-37ae-5c33-9bcd-b059b3a3cf77", "subject_id": "c340f74e-6c94-59c8-a56d-97c4f6264408", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李琪：由尚书右丞任中书侍郎、同平章事者。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p005·原文件第20行", "note": "原文：夏，四月，乙亥，以尚书右丞李琪为中书侍郎、同平章事。；核对说明：与既有规范名合并；繁简或异体仅用于实体匹配，引用保留原字。", "status": "draft", "id": "95290d68-916c-5b66-83c9-5a43e53c05d9", "subject_id": "47cd5942-1269-5f38-8771-914c2baf55ba", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李琪：由尚书右丞任中书侍郎、同平章事者。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p005·原文件第20行", "note": "原文：夏，四月，乙亥，以尚书右丞李琪为中书侍郎、同平章事。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "96e7327c-d207-55ab-933c-f749d2588600", "subject_id": "d64e09e7-88ff-5b11-ae8c-8146a4a277d0", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》卷十同记以李琪为中书侍郎、平章事。", "citation": "《旧五代史》卷十，段落 jiu-wudaishi-205deb4a7860-p000439；EPUB电子本，纸本及异文待核", "note": "原文：以尚書左丞李琪為中書侍郎、平章事。；核对说明：旧书作尚书左丞，主书作尚书右丞；保留原文职衔异文，任相事实相合。", "status": "draft", "id": "c9d79316-20c7-5434-9ad9-0b752d198cf8", "subject_id": "c340f74e-6c94-59c8-a56d-97c4f6264408", "source_id": "f8a7ab84-b0c2-5b60-89ec-6771e2df98d0"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李珽：李琪之兄。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p005·原文件第20行", "note": "原文：琪，珽之弟也，；核对说明：与既有规范名合并；繁简或异体仅用于实体匹配，引用保留原字。", "status": "draft", "id": "f443c854-d455-5e3b-b3f9-e181e7129924", "subject_id": "eee3e8f9-b8eb-571e-9520-2d58cf9bb6da", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "person_relationship", "field_path": "description", "claim_text": "李珽是李琪的兄长。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p005·原文件第20行", "note": "原文：琪，珽之弟也，；核对说明：由“李琪是李珽之弟”转写为有向兄长关系。", "status": "draft", "id": "ed939b77-b1ea-5d66-9cc0-643e159b3fc8", "subject_id": "61ddca48-692d-50b3-9436-88078b11f32e", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "event", "field_path": "description", "claim_text": "萧顷奏李琪改摄为守，李琪被罢为太子少保。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p005·原文件第20行", "note": "原文：萧顷与琪同为相，顷谨密而阴伺琪短。久之，有以摄官求仕者，琪辄改摄为守，顷奏之。帝大怒，欲流琪远方，赵、张左右之，止罢为太子少保。；核对说明：“久之”是追叙，未强定此事仍发生于920；“欲流”未实际流放。", "status": "draft", "id": "849695d3-edb5-5089-9dd0-2f7a14476f0b", "subject_id": "1f17da58-4be4-56e0-8fd2-7bb53648e461", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "李琪四月任相后“久之”；确年、月、日未载", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p005·原文件第20行", "note": "原文：萧顷与琪同为相，顷谨密而阴伺琪短。久之，有以摄官求仕者，琪辄改摄为守，顷奏之。帝大怒，欲流琪远方，赵、张左右之，止罢为太子少保。；核对说明：按主书本段纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "ddcedf79-6922-5636-8f72-e79dc9a26ad5", "subject_id": "1f17da58-4be4-56e0-8fd2-7bb53648e461", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李琪：被萧顷奏劾后罢相为太子少保者。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p005·原文件第20行", "note": "原文：萧顷与琪同为相，顷谨密而阴伺琪短。久之，有以摄官求仕者，琪辄改摄为守，顷奏之